import { Injectable } from '@nestjs/common';
import { InjectGraphObjectManager, GraphObjectManager } from '@liberation-data/drivine';
import { PersonCareer } from './person-career';

@Injectable()
export class CareerService {
  constructor(
    @InjectGraphObjectManager() private readonly gom: GraphObjectManager,
  ) {}

  leads() {
    return this.gom.loadAll(PersonCareer, (q) => ({
      where: q.person.bio.containsIgnoreCase('lead'),
    }));
  }
}

